(function(){
  var repostTarget=null;
  var screens={feed:document.getElementById('feed'),chat:document.getElementById('chat'),profile:document.getElementById('profile'),discover:document.getElementById('discover'),business:document.getElementById('business'),group:document.getElementById('group')};
  var chips=document.querySelectorAll('.chip');
  function go(n){
    Object.keys(screens).forEach(function(k){screens[k].classList.toggle('active',k===n);});
    chips.forEach(function(c){if(c.dataset.go)c.classList.toggle('on',c.dataset.go===n);});
    if(n==='chat'){var s=document.getElementById('stream');s.scrollTop=s.scrollHeight;}
  }

  var toastEl=document.getElementById('toast'),tid;
  function toast(m){toastEl.textContent=m;toastEl.classList.add('show');
    clearTimeout(tid);tid=setTimeout(function(){toastEl.classList.remove('show');},1800);}

  document.addEventListener('click',function(e){
    var g=e.target.closest('[data-go]'); if(g){go(g.dataset.go);return;}
    var t=e.target.closest('[data-toast]'); if(t){toast(t.dataset.toast);return;}
  });

  /* ---------- sheet ---------- */
  var sheet=document.getElementById('sheet'),scrim=document.getElementById('scrim');
  function openSheet(){sheet.classList.add('show');scrim.classList.add('show');}
  function closeSheet(){sheet.classList.remove('show');scrim.classList.remove('show');}
  document.querySelectorAll('[data-open-sheet]').forEach(function(el){el.addEventListener('click',openSheet);});
  document.getElementById('openSheetTop').addEventListener('click',openSheet);
  scrim.addEventListener('click',function(){closeSheet();closeShare();closeCm();});

  /* type switch */
  var curType='feel';
  document.querySelectorAll('.type[data-type]').forEach(function(el){
    el.addEventListener('click',function(){
      document.querySelectorAll('.type').forEach(function(x){x.classList.remove('on');});
      el.classList.add('on'); curType=el.dataset.type;
      document.getElementById('submitPost').textContent =
        curType==='feel' ? 'Post to Nearby' : (curType==='loc' ? 'Share this place' : 'Post photo');
      ta.placeholder = curType==='feel' ? ('Share why you feel ' + mood.toLowerCase() + '\u2026')
                     : curType==='loc' ? 'What makes this place worth a visit?'
                     : 'Add a caption for your photo\u2026';
    });
  });
  document.querySelectorAll('[data-soon]').forEach(function(el){
    el.addEventListener('click',function(){toast('Business pages arrive in v3');});
  });

  /* moods */
  var mood='Grateful';
  document.querySelectorAll('.mood-chip').forEach(function(el){
    el.addEventListener('click',function(){
      document.querySelectorAll('.mood-chip').forEach(function(x){x.classList.remove('on');});
      el.classList.add('on'); mood=el.dataset.mood;
      ta.placeholder = 'Share why you feel ' + mood.toLowerCase() + '\u2026';
    });
  });

  /* counter + enable */
  var ta=document.getElementById('postText'),cc=document.getElementById('charCount'),
      submit=document.getElementById('submitPost');
  ta.addEventListener('input',function(){
    cc.textContent=ta.value.length;
    submit.disabled = ta.value.trim().length<3;
  });

  /* reactions */
  document.querySelectorAll('[data-rx]').forEach(function(el){
    el.addEventListener('click',function(){
      var on=el.classList.toggle('on'), c=el.querySelector('.c');
      var n=parseInt(c.textContent.replace(/,/g,''),10)||0;
      c.textContent=(n+(on?1:-1)).toLocaleString('en-US');
    });
  });

  /* hug */
  document.querySelectorAll('[data-hug]').forEach(function(btn){
    btn.addEventListener('click',function(){
      if(btn.classList.contains('done'))return;
      btn.classList.add('done'); btn.textContent='🤗 Hug sent';
      toast('A hug was sent — quietly, no notification');
    });
  });

  /* feed filter */
  var filter='foryou';
  document.querySelectorAll('[data-filter]').forEach(function(el){
    el.addEventListener('click',function(){
      document.querySelectorAll('[data-filter]').forEach(function(x){x.classList.remove('on');});
      el.classList.add('on'); filter=el.dataset.filter;
      document.querySelectorAll('.post').forEach(function(p){
        var show = filter==='foryou' || p.dataset.nearby==='1';
        p.style.display = show ? '' : 'none';
      });
      document.getElementById('feedScroll').scrollTop=0;
      toast(filter==='nearby' ? 'Showing posts within 2 km' : 'Mixed feed — video, feelings, places');
    });
  });

  /* submit post */
  submit.addEventListener('click',function(){
    var text=ta.value.trim(); if(!text)return;
    if(repostTarget){
      var rp=document.createElement('article');
      rp.className='post feel'; rp.dataset.nearby='1'; rp.dataset.score='99';
      rp.innerHTML='<div class="why"><i class="material-icons">auto_awesome</i><span>You shared this with your followers</span></div>'+
        '<div class="quote"></div>'+
        '<div class="shared-preview"><div class="sp-w"></div><div class="sp-t"></div></div>'+
        '<div class="feel-author"><div class="av"></div><div><div class="who">You</div>'+
        '<div class="sub"><span>@you</span> · <span>just now</span> · <i class="material-icons">place</i>Inya Lake</div></div></div>'+
        '<div class="pbar"><div class="pb" data-react><i class="material-icons">favorite_border</i><span class="rc">0</span></div>'+
        '<div class="pb" data-comment><i class="material-icons">chat_bubble_outline</i><span class="cc">0</span></div>'+
        '<div class="pb" data-share><i class="material-icons">ios_share</i><span class="sc">0</span></div>'+
        '<div class="pb save" data-save><i class="material-icons">bookmark_border</i></div></div>';
      rp.querySelector('.quote').textContent=text;
      rp.querySelector('.sp-w').textContent='Originally by '+repostTarget.author;
      rp.querySelector('.sp-t').textContent=repostTarget.snippet;
      feedScroll.insertBefore(rp,feedScroll.firstChild);
      posts.unshift(rp);
      ta.value=''; cc.textContent='0'; submit.disabled=true; repostTarget=null;
      document.querySelector('#sheet h3').textContent='Share something';
      document.querySelector('#sheet .hint').textContent='Two taps is enough. Pick a type, write one line.';
      document.getElementById('submitPost').textContent='Post to Nearby';
      closeSheet(); go('feed'); feedScroll.scrollTop=0;
      toast('Shared to your profile · credit kept');
      return;
    }
    var el=document.createElement('article');
    el.className='post feel'; el.dataset.type='feel'; el.dataset.nearby='1';
    el.innerHTML=
      '<div class="top-tag"><span class="loc-pill"><i class="material-icons">place</i>JUST NOW · 0 m</span></div>'+
      '<div class="mood"><i class="material-icons">auto_awesome</i>'+mood.toUpperCase()+'</div>'+
      '<div class="quote"></div>'+
      '<div class="feel-author"><div class="av ini">TA</div><div>'+
        '<div class="who">You</div>'+
        '<div class="sub"><span>@you</span> · <span>just now</span> · <i class="material-icons">place</i>Inya Lake</div>'+
      '</div></div>'+
      '<div class="react-row">'+
        '<div class="rx" data-rx><em>❤️</em><span class="c">0</span></div>'+
        '<div class="rx" data-rx><em>🤗</em><span class="c">0</span></div>'+
        '<div class="rx" data-rx><em>💪</em><span class="c">0</span></div>'+
      '</div>'+
      '<button class="hug" data-hug>🤗 Send a hug</button>';
    el.querySelector('.quote').textContent=text;
    var scroll=document.getElementById('feedScroll');
    scroll.insertBefore(el,scroll.firstChild);
    scroll.scrollTop=0;
    ta.value=''; cc.textContent='0'; submit.disabled=true;
    closeSheet(); go('feed');
    toast('Posted · visible to people within 2 km');
    el.querySelectorAll('[data-rx]').forEach(function(x){
      x.addEventListener('click',function(){
        var on=x.classList.toggle('on'),c=x.querySelector('.c');
        var n=parseInt(c.textContent,10)||0;c.textContent=n+(on?1:-1);
      });
    });
    el.querySelector('[data-hug]').addEventListener('click',function(){
      if(this.classList.contains('done'))return;
      this.classList.add('done');this.textContent='🤗 Hug sent';
    });
  });

  /* like on video */
  document.querySelectorAll('.like-btn').forEach(function(b){
    b.addEventListener('click',function(){
      var on=b.classList.toggle('on'), ic=b.querySelector('.material-icons'), c=b.querySelector('.like-count');
      ic.textContent=on?'favorite':'favorite_border';
      c.textContent=on?'12.5K':'12.4K';
    });
  });

  /* discover tabs + search */
  var dsCards=Array.prototype.slice.call(document.querySelectorAll('.ds-card'));
  var dsTab='groups';
  function applyDs(){
    var q=(document.getElementById('dsInput').value||'').trim().toLowerCase();
    dsCards.forEach(function(c){
      var okTab=(c.dataset.tab===dsTab), okQ=(!q||c.textContent.toLowerCase().indexOf(q)>-1);
      c.style.display=(okTab&&okQ)?'':'none';
    });
  }
  document.querySelectorAll('[data-dstab]').forEach(function(el){
    el.addEventListener('click',function(){
      document.querySelectorAll('[data-dstab]').forEach(function(x){x.classList.remove('on');});
      el.classList.add('on'); dsTab=el.dataset.dstab; applyDs();
    });
  });
  document.getElementById('dsInput').addEventListener('input',applyDs);
  applyDs();

  /* follow / join toggles */
  document.querySelectorAll('[data-toggle-join]').forEach(function(b){
    b.addEventListener('click',function(e){
      e.stopPropagation();
      var on=b.classList.toggle('on');
      var label=b.textContent.trim();
      if(label==='Joined'||label==='Following'){ b.textContent=on?'Joined':'Join'; }
      else { b.textContent=on?'Following':'Follow'; }
      if(on) toast(b.textContent==='Joined'?'Joined the group':'Now following');
      else b.textContent=(label==='Joined')?'Join':'Follow';
    });
  });

  /* group join */
  var gj=document.getElementById('grpJoin'), gl=document.getElementById('grpLeave');
  if(gj){gj.addEventListener('click',function(){
    if(gj.classList.contains('joined'))return;
    gj.classList.add('joined'); gj.textContent='Joined';
    if(gl) gl.classList.add('show');
    toast('Joined Inya Lake Runners');
  });}
  if(gl){gl.addEventListener('click',function(){
    gj.classList.remove('joined'); gj.textContent='Join group';
    gl.classList.remove('show');
    toast('You left the group');
  });}

  /* chat */
  var input=document.getElementById('msgInput'),send=document.getElementById('sendBtn'),
      stream=document.getElementById('stream'),typing=document.getElementById('typing');
  var replies=['Nice — send me the export when it is done.','That works. Let us schedule it for 8pm.','Love it. The colour grade feels right.'];
  var ri=0;
  function sendMsg(){
    var v=input.value.trim(); if(!v)return;
    var b=document.createElement('div'); b.className='bubble out'; b.textContent=v;
    stream.insertBefore(b,typing); input.value=''; stream.scrollTop=stream.scrollHeight;
    typing.classList.add('show'); stream.scrollTop=stream.scrollHeight;
    setTimeout(function(){
      typing.classList.remove('show');
      var r=document.createElement('div'); r.className='bubble in'; r.textContent=replies[ri++%replies.length];
      stream.insertBefore(r,typing); stream.scrollTop=stream.scrollHeight;
    },1200);
  }
  send.addEventListener('click',sendMsg);
  input.addEventListener('keydown',function(e){if(e.key==='Enter')sendMsg();});

  /* profile grid */
  var sets={
    videos:[['12.4K','52% 12%','180%'],['8.1K','30% 40%','220%'],['22.7K','70% 30%','160%'],
            ['3.2K','45% 65%','240%'],['14.9K','60% 20%','150%'],['9.6K','38% 55%','260%']],
    liked:[['6.4K','62% 45%','170%'],['31.2K','20% 25%','210%'],['4.8K','55% 70%','190%'],
           ['11.5K','75% 35%','230%'],['2.9K','42% 18%','250%'],['17.3K','68% 60%','165%']],
    saved:[['5.1K','48% 30%','200%'],['9.9K','35% 62%','175%'],['13.6K','58% 15%','245%'],
           ['7.2K','72% 48%','155%'],['19.4K','25% 45%','215%'],['4.3K','63% 72%','185%']]
  };
  var grid=document.getElementById('grid');
  function renderGrid(k){
    grid.innerHTML='';
    sets[k].forEach(function(it){
      var c=document.createElement('div'); c.className='cell';
      c.style.backgroundPosition=it[1]; c.style.backgroundSize=it[2];
      var s=document.createElement('span'); s.textContent='\u25B6 '+it[0]; c.appendChild(s);
      c.addEventListener('click',function(){toast('Open video · '+it[0]+' views');});
      grid.appendChild(c);
    });
  }
  renderGrid('videos');

  /* ================= v4: ranking, share, comments, notifications ================= */
  var feedScroll=document.getElementById('feedScroll');
  var secNote=document.getElementById('secNote');
  var posts=Array.prototype.slice.call(feedScroll.querySelectorAll('.post'));
  var curFilter='foryou';

  function applyFeed(){
    var list=posts.slice();
    if(curFilter==='nearby'){
      list=list.filter(function(p){return p.dataset.nearby==='1'||p.dataset.friend==='1';});
      list.sort(function(a,b){
        var fa=+a.dataset.friend, fb=+b.dataset.friend;
        if(fa!==fb) return fb-fa;
        return +b.dataset.score - +a.dataset.score;
      });
      secNote.classList.add('show');
    }else{
      list.sort(function(a,b){return +b.dataset.score-+a.dataset.score;});
      secNote.classList.remove('show');
    }
    list.forEach(function(p){feedScroll.appendChild(p);});
    posts.forEach(function(p){ if(list.indexOf(p)<0) p.style.display='none'; else p.style.display='';});
    feedScroll.scrollTop=0;
  }

  document.querySelectorAll('[data-filter]').forEach(function(el){
    el.addEventListener('click',function(){
      document.querySelectorAll('[data-filter]').forEach(function(x){x.classList.remove('on');});
      el.classList.add('on'); curFilter=el.dataset.filter; applyFeed();
      toast(curFilter==='nearby'?'Nearby · friends first, then within 2 km':'For You · ranked by your activity');
    });
  });

  applyFeed();

  /* ---- reactions / save ---- */
  posts.forEach(function(p){
    p.querySelectorAll('[data-react]').forEach(function(b){
      b.addEventListener('click',function(e){
        e.stopPropagation();
        var on=b.classList.toggle('on'), c=b.querySelector('.rc');
        b.querySelector('.material-icons').textContent=on?'favorite':'favorite_border';
        if(c){var n=parseInt(c.textContent.replace(/,/g,''),10)||0;
          c.textContent=(n+(on?1:-1)).toLocaleString('en-US');}
      });
    });
    p.querySelectorAll('[data-save]').forEach(function(b){
      b.addEventListener('click',function(e){
        e.stopPropagation();
        var on=b.classList.toggle('on');
        var ic=b.querySelector('.material-icons');
        if(ic) ic.textContent=on?'bookmark':'bookmark_border';
        toast(on?'Saved to your collection':'Removed from saved');
      });
    });
  });

  /* ---- share sheet ---- */
  var shareSheet=document.getElementById('shareSheet'), shareUrl=document.getElementById('shareUrl'),
      shareHint=document.getElementById('shareHint'), curPost=null;

  function closeShare(){ shareSheet.classList.remove('show'); scrim.classList.remove('show'); }
  document.getElementById('shareClose').addEventListener('click',closeShare);
  document.getElementById('cmClose').addEventListener('click',function(){closeCm();});
  function closeCm(){ if(cmSheet){cmSheet.classList.remove('show');} scrim.classList.remove('show'); }
  function openShare(p){
    curPost=p;
    shareUrl.textContent='nexus.app/p/'+p.dataset.id;
    shareHint.textContent='Anyone with the link can open it · public post';
    shareSheet.classList.add('show'); scrim.classList.add('show');
  }
  posts.forEach(function(p){
    p.querySelectorAll('[data-share]').forEach(function(b){
      b.addEventListener('click',function(e){e.stopPropagation();openShare(p);});
    });
  });

  document.getElementById('copyLink').addEventListener('click',function(){
    var t=shareUrl.textContent, full='https://'+t;
    function fallback(){
      var ta=document.createElement('textarea'); ta.value=full;
      ta.style.position='fixed'; ta.style.opacity='0';
      document.body.appendChild(ta); ta.select();
      try{document.execCommand('copy');}catch(e){}
      document.body.removeChild(ta);
    }
    if(navigator.clipboard && window.isSecureContext){
      navigator.clipboard.writeText(full).catch(fallback);
    } else { fallback(); }
    toast('Link copied · '+t);
  });

  document.querySelectorAll('[data-share-out]').forEach(function(el){
    el.addEventListener('click',function(){
      closeShare();
      toast('Opening '+el.dataset.shareOut+'…');
    });
  });
  document.querySelector('[data-share-save]').addEventListener('click',function(){
    closeShare(); toast('Post saved to your collection');
  });
  document.querySelector('[data-share-qr]').addEventListener('click',function(){
    toast('QR code ready to scan');
  });

  /* share to own profile -> quote repost */
  document.querySelector('[data-share-own]').addEventListener('click',function(){
    var author='Thiri Aung', snippet='Some evenings I just sit by the lake and let the day go.';
    if(curPost && curPost.dataset.id==='p3'){author='Kyaw Zin';snippet='Sunset at Inya Lake — best light around 5:40pm.';}
    if(curPost && curPost.dataset.id==='p1'){author='Sophie Jap';snippet='Editorial video — shot by the lake at golden hour.';}
    if(curPost && curPost.dataset.id==='p5'){author='Shwe Kyaung Coffee';snippet='20% off before 10am — mohinga and iced latte.';}
    closeShare();
    repostTarget={author:author,snippet:snippet};
    document.getElementById('postText').value='';
    document.getElementById('charCount').textContent='0';
    document.getElementById('submitPost').disabled=true;
    document.querySelector('#sheet h3').textContent='Share to your profile';
    document.querySelector('#sheet .hint').textContent='Add your own words — the original stays credited';
    document.getElementById('submitPost').textContent='Share post';
    openSheet();
  });

  /* ---- comments ---- */
  var cmSheet=document.getElementById('cmSheet'),cmList=document.getElementById('cmList'),
      cmInput=document.getElementById('cmInput'),cmCount=document.getElementById('cmCount'),
      cmOn=document.getElementById('cmOn'),activePost=null;

  var seed=[
    {who:'Ko Min',ini:'KM',tx:'This is exactly what I needed to read today.',mt:'4 min'},
    {who:'Thiri Aung',ini:'TA',tx:'Come sit by the lake with me next time.',mt:'2 min',me:true}
  ];

  function renderComments(list){
    cmList.innerHTML='';
    list.forEach(function(c){
      var d=document.createElement('div'); d.className='cm';
      d.innerHTML='<div class="av">'+c.ini+'</div><div><div class="who">'+c.who+
        '</div><div class="tx"></div><div class="mt"><span>Reply</span><span>Like</span><span>'+c.mt+'</span></div></div>';
      d.querySelector('.tx').textContent=c.tx;
      cmList.appendChild(d);
    });
    cmCount.textContent='('+list.length+')';
  }
  renderComments(seed);

  posts.forEach(function(p){
    p.querySelectorAll('[data-comment]').forEach(function(b){
      b.addEventListener('click',function(e){
        e.stopPropagation();
        activePost=p;
        cmOn.textContent='Reply as @you · comments notify the author';
        cmSheet.classList.add('show'); scrim.classList.add('show');
        renderComments(seed);
        setTimeout(function(){cmInput.focus();},250);
      });
    });
  });

  function sendComment(){
    var v=cmInput.value.trim(); if(!v)return;
    seed.push({who:'You',ini:'YO',tx:v,mt:'now',me:true});
    renderComments(seed); cmInput.value=''; cmList.scrollTop=cmList.scrollHeight;
    if(activePost){
      var c=activePost.querySelector('[data-comment] .cc');
      if(c){var n=parseInt(c.textContent.replace(/,/g,''),10)||0;c.textContent=(n+1).toLocaleString('en-US');}
    }
    toast('Reply sent · author notified');
  }
  document.getElementById('cmSend').addEventListener('click',sendComment);
  cmInput.addEventListener('keydown',function(e){if(e.key==='Enter')sendComment();});

  /* ---- notifications ---- */
  var npanel=document.getElementById('npanel'), bell=document.getElementById('bell');
  bell.addEventListener('click',function(){
    npanel.classList.add('show');
  });
  document.getElementById('npClose').addEventListener('click',function(){npanel.classList.remove('show');});
  document.getElementById('markAll').addEventListener('click',function(){
    document.querySelectorAll('.np.unread').forEach(function(x){x.classList.remove('unread');});
    bell.classList.add('read'); toast('All notifications read');
  });
  document.querySelectorAll('.np').forEach(function(n){
    n.addEventListener('click',function(){
      n.classList.remove('unread');
      var k=n.dataset.np;
      npanel.classList.remove('show');
      if(k==='comment'){ cmSheet.classList.add('show'); scrim.classList.add('show'); renderComments(seed); }
      else if(k==='react'){ toast('12 reactions on your feeling post'); }
      else if(k==='share'){ toast('Nang Seng shared your post'); }
      else if(k==='group'){ go('group'); }
      else if(k==='biz'){ go('business'); }
    });
  });

  /* ---- business tab ---- */
  var btypeRow=document.getElementById('btype'), curBtype='all';
  var origApply=applyDs;
  function applyDsBiz(){
    var q=(document.getElementById('dsInput').value||'').trim().toLowerCase();
    dsCards.forEach(function(c){
      var okTab=(c.dataset.tab===dsTab), okQ=(!q||c.textContent.toLowerCase().indexOf(q)>-1);
      var okType=(curBtype==='all'||c.dataset.btype===curBtype);
      c.style.display=(okTab&&okQ&&okType)?'':'none';
    });
    btypeRow.style.display=(dsTab==='business')?'flex':'none';
  }
  document.querySelectorAll('[data-dstab]').forEach(function(el){
    el.addEventListener('click',function(){ curBtype='all';
      document.querySelectorAll('.bt').forEach(function(x){x.classList.remove('on');});
      document.querySelector('.bt[data-btype="all"]').classList.add('on');
      setTimeout(applyDsBiz,0);
    });
  });
  document.querySelectorAll('.bt[data-btype]').forEach(function(el){
    el.addEventListener('click',function(){
      document.querySelectorAll('.bt').forEach(function(x){x.classList.remove('on');});
      el.classList.add('on'); curBtype=el.dataset.btype; applyDsBiz();
    });
  });
  document.getElementById('dsInput').addEventListener('input',applyDsBiz);
  applyDsBiz();

  /* ---- repost target ---- */
  repostTarget=null;

  document.querySelectorAll('[data-ptab]').forEach(function(el){
    el.addEventListener('click',function(){
      document.querySelectorAll('[data-ptab]').forEach(function(x){x.classList.remove('on');});
      el.classList.add('on'); renderGrid(el.dataset.ptab);
    });
  });
})();
